workedExamples.question_text:
Find the area of this rectangle in simplest form.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\draw (0,0) rectangle (4.2,2.8);
\path (2.1,0) node[below] {$\sqrt{54}\text{ cm}$};
\path (0,1.4) node[left] {$\sqrt{24}\text{ cm}$};
\end{tikzpicture}
[/tikz]

Find the area of this triangle in simplest form.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\draw (0,0)--(4,0)--(2,3)--cycle;
\draw[dashed] (2,3)--(2,0);
\draw (2,0.22)--(2.22,0.22)--(2.22,0);
\path (2,0) node[below] {$\sqrt{28}\text{ cm}$};
\path (4.5,1.5) node[anchor=west,inner sep=2pt] (heightlabel) {$\sqrt{63}\text{ cm}$};
\draw[->,thin] (heightlabel.west)--(2,1.5);
\end{tikzpicture}
[/tikz]

Find the perimeter of this rectangle in simplest form.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\draw (0,0) rectangle (4.2,2.8);
\path (2.1,0) node[below] {$\sqrt{108}\text{ m}$};
\path (0,1.4) node[left] {$\sqrt{48}\text{ m}$};
\end{tikzpicture}
[/tikz]

development.question_text:
Find the area of this rectangle in simplest form.
[tikz]
\begin{tikzpicture}
\coordinate (A) at (0,0);
\coordinate (B) at (4.95,0);
\coordinate (C) at (4.95,1.98);
\coordinate (D) at (0,1.98);
\draw (A) -- (B) node[midway,below] {$\sqrt{50}\text{ cm}$};
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A) node[midway,left] {$\sqrt{8}\text{ cm}$};
\end{tikzpicture}
[/tikz]

Find the perimeter of this rectangle in simplest form.
[tikz]
\begin{tikzpicture}
\coordinate (A) at (0,0);
\coordinate (B) at (4.53,0);
\coordinate (C) at (4.53,3.39);
\coordinate (D) at (0,3.39);
\draw (A) -- (B) node[midway,below] {$\sqrt{32}\text{ cm}$};
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A) node[midway,left] {$\sqrt{18}\text{ cm}$};
\end{tikzpicture}
[/tikz]

Find the area of this triangle in simplest form.
[tikz]
\begin{tikzpicture}
\coordinate (A) at (0,0);
\coordinate (B) at (2.46,0);
\coordinate (C) at (1.6,3.69);
\coordinate (F) at (1.6,0);
\draw (A) -- (B) node[midway,below] {$\sqrt{20}\text{ cm}$};
\draw (B) -- (C);
\draw (C) -- (A);
\draw[dashed] (C) -- (F) node[midway,fill=white,inner sep=1pt] {$\sqrt{45}\text{ cm}$};
\draw (1.6,0.22) -- (1.82,0.22) -- (1.82,0);
\end{tikzpicture}
[/tikz]

mastery.question_text:
Find the area and the perimeter of this rectangle, each in simplest form.
[tikz]
\begin{tikzpicture}
\coordinate (A) at (0,0);
\coordinate (B) at (4.157,0);
\coordinate (C) at (4.157,3.118);
\coordinate (D) at (0,3.118);
\draw (A) -- (B) node[midway,below] {$2\sqrt{12}\text{ m}$};
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A) node[midway,left] {$\sqrt{27}\text{ m}$};
\end{tikzpicture}
[/tikz]
